import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import \* as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma.service';
import { LoginResult } from './dto/login.dto';

\@Injectable()
export class AuthService {
  constructor(private readonly prisma: PrismaService, private readonly jwtService: JwtService) {}

  // Validate email/password and return JWT
  async validateUserByEmailPassword(email: string, password: string): Promise<LoginResult> {
    const user = await this.prisma.user.findUnique({ where: { email }, include: { password: true } });
    if (!user || !user.password) throw new UnauthorizedException('Invalid credentials');

    const match = await bcrypt.compare(password, user.password.hash);
    if (!match) throw new UnauthorizedException('Invalid credentials');

    const payload = { sub: user.id, email: user.email, role: user.role };
    const accessToken = this.jwtService.sign(payload);
    return { accessToken, expiresIn: process.env.JWT\_EXPIRES\_IN || '1h' };
  }

  async signJwtForUser(userId: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new UnauthorizedException('User not found');
    const payload = { sub: user.id, email: user.email, role: user.role };
    return { accessToken: this.jwtService.sign(payload), expiresIn: process.env.JWT\_EXPIRES\_IN || '1h' };
  }

  // Upsert a user created by OAuth provider
  async upsertOAuthUser(provider: string, providerAccountId: string, profile: { email?: string; name?: string; image?: string }): Promise<{ userId: string } & LoginResult> {
    // attempt to find existing account
    const account = await this.prisma.account.findUnique({ where: { provider\_providerAccountId: { provider, providerAccountId } }, include: { createdBy: true } });

    if (account) {
      const jwt = await this.signJwtForUser(account.createdById);
      return { userId: account.createdById, ...jwt };
    }

    // if no account, find or create user by email
    let user = null;
    if (profile.email) {
      user = await this.prisma.user.findUnique({ where: { email: profile.email } });
    }

    if (!user) {
      user = await this.prisma.user.create({
        data: { email: profile.email ?? `${provider}-${providerAccountId}@noemail.local`, name: profile.name, image: profile.image },
      });
    }

    // create account
    await this.prisma.account.create({
      data: {
        provider,
        providerAccountId,
        createdById: user.id,
      },
    });

    const jwt = await this.signJwtForUser(user.id);
    return { userId: user.id, ...jwt };
  }
}

import { Controller, Post, Body, UseGuards, Req, Get, Res, HttpCode } from '@nestjs/common';
import { Response } from 'express';
import { AuthService } from './auth.service';
import { LoginDto } from './dto/login.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { Request } from 'express';
import \* as passport from 'passport';

\@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('login')
  @HttpCode(200)
  async login(@Body() dto: LoginDto) {
    return this.authService.validateUserByEmailPassword(dto.email, dto.password);
  }

  // OAuth start endpoints
  @Get('oauth/google')
  googleAuth(@Req() req: Request, @Res() res: Response) {
    return passport.authenticate('google', { scope: \['email', 'profile'], session: false })(req, res);
  }

  @Get('oauth/github')
  githubAuth(@Req() req: Request, @Res() res: Response) {
    return passport.authenticate('github', { scope: \['user\:email'], session: false })(req, res);
  }

  // OAuth callback endpoints
  @Get('oauth/google/callback')
  async googleCallback(@Req() req: Request, @Res() res: Response) {
    return passport.authenticate('google', { session: false }, async (err, user, info) => {
      // Passport strategy returns profile in info
      if (err) return res.status(500).json({ message: 'OAuth error', detail: err });
      if (!info) return res.status(400).json({ message: 'No profile returned' });

      // info should contain providerAccountId and profile
      const { providerAccountId, profile } = info as any;
      const result = await this.authService.upsertOAuthUser('google', providerAccountId, profile);

      // send token to client - for SPA we'll redirect to frontend with token
      const redirectBase = process.env.FRONTEND\_BASE\_URL || 'http\://localhost:5173';
      return res.redirect(`${redirectBase}/auth/success?token=${result.accessToken}`);
    })(req, res);
  }

  @Get('oauth/github/callback')
  async githubCallback(@Req() req: Request, @Res() res: Response) {
    return passport.authenticate('github', { session: false }, async (err, user, info) => {
      if (err) return res.status(500).json({ message: 'OAuth error', detail: err });
      if (!info) return res.status(400).json({ message: 'No profile returned' });
      const { providerAccountId, profile } = info as any;
      const result = await this.authService.upsertOAuthUser('github', providerAccountId, profile);
      const redirectBase = process.env.FRONTEND\_BASE\_URL || 'http\://localhost:5173';
      return res.redirect(`${redirectBase}/auth/success?token=${result.accessToken}`);
    })(req, res);
  }

  @UseGuards(JwtAuthGuard)
  @Get('me')
  async me(@Req() req: Request) {
    // Provided by JwtStrategy
    return (req as any).user;
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { PrismaService } from '../prisma.service';

\@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly prisma: PrismaService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: process.env.JWT\_SECRET || 'replace-me',
    });
  }

  async validate(payload: any) {
    const user = await this.prisma.user.findUnique({ where: { id: payload.sub } });
    if (!user) throw new UnauthorizedException('User not found');
    return { id: user.id, email: user.email, role: user.role };
  }
}

