import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-google-oauth20';

\@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  constructor() {
    super({
      clientID: process.env.GOOGLE\_CLIENT\_ID || '',
      clientSecret: process.env.GOOGLE\_CLIENT\_SECRET || '',
      callbackURL: (process.env.OAUTH\_CALLBACK\_BASE\_URL || 'http\://localhost:4000') + '/auth/oauth/google/callback',
      passReqToCallback: false,
    });
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  async validate(\_accessToken: string, \_refreshToken: string, profile: any, done: Function) {
    // profile contains emails and id
    try {
      const providerAccountId = profile.id;
      const userProfile = {
        email: profile.emails?.\[0]?.value,
        name: profile.displayName,
        image: profile.photos?.\[0]?.value,
      };

      // Pass info to controller through

 argument
      done(null, null, { providerAccountId, profile: userProfile });
    } catch (err) {
      done(err, null);
    }
  }
}

import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-github2';

\@Injectable()
export class GithubStrategy extends PassportStrategy(Strategy, 'github') {
  constructor() {
    super({
      clientID: process.env.GITHUB\_CLIENT\_ID || '',
      clientSecret: process.env.GITHUB\_CLIENT\_SECRET || '',
      callbackURL: (process.env.OAUTH\_CALLBACK\_BASE\_URL || 'http\://localhost:4000') + '/auth/oauth/github/callback',
      scope: \['user\:email'],
      passReqToCallback: false,
    });
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  async validate(\_accessToken: string, \_refreshToken: string, profile: any, done: Function) {
    try {
      // Github may return multiple emails; prefer primary
      const providerAccountId = profile.id;
      const email = profile.emails?.find((e: any) => e.primary)?.value || profile.emails?.\[0]?.value;
      const userProfile = { email, name: profile.displayName || profile.username, image: profile.photos?.\[0]?.value };
      done(null, null, { providerAccountId, profile: userProfile });
    } catch (err) {
      done(err, null);
    }
  }
}

