export interface CreateOrganizationDto {
  name: string;
  industry?: string | null;
}

\@Injectable()
export class OrganizationService {
  constructor(private readonly prisma: PrismaService) {}

  async createOrganization(userId: string, dto: CreateOrganizationDto) {
    // create organization and relate to user as createdBy
    const org = await this.prisma.organization.create({
      data: { name: dto.name, industry: dto.industry ?? null, createdById: userId },
    });
    return org;
  }

  async listOrganizationsForUser(userId: string) {
    return this.prisma.organization.findMany({ where: { createdById: userId }, orderBy: { createdAt: 'desc' } });
  }
}

