import { atom } from 'nanostores';

type User = { id?: string; email?: string; role?: string } | null;

interface AuthState {
  token: string | null;
  user: User;
}

export const authStore = atom<AuthState>({ token: null, user: null });

export const setUser = (user: User) => {
  authStore.setKey('user', user);
};

export const setToken = (token: string | null) => {
  if (token) localStorage.setItem('auth\_token', token);
  else localStorage.removeItem('auth\_token');
  authStore.setKey('token', token);

  if (token) {
    // naive decode JWT payload (no verification) to extract minimal user info
    try {
      const parts = token.split('.');
      if (parts.length === 3) {
        const payload = JSON.parse(atob(parts\[1]));
        setUser({ id: payload.sub, email: payload.email, role: payload.role });
      }
    } catch (err) {
      // ignore
    }
  } else {
    setUser(null);
  }
};

// initialize from localStorage
const init = () => {
  const t = localStorage.getItem('auth\_token');
  if (t) setToken(t);
};
init();

export const authActions = { setToken, setUser };

import axios from 'axios';
import { authStore } from '../stores/authStore';

const API\_BASE = import.meta.env.VITE\_API\_BASE || 'http\://localhost:4000';

export const apiClient = axios.create({ baseURL: API\_BASE, withCredentials: true });

// Attach token to requests automatically
apiClient.interceptors.request.use((config) => {
  const token = authStore.get().token;
  if (token) config.headers = { ...(config.headers || {}), Authorization: `Bearer ${token}` };
  return config;
});

// handle responses where frontend needs to capture token from redirect
// e.g., if backend returns token in query param /auth/success?token=...

export async function captureTokenFromUrlIfPresent() {
  try {
    const params = new URLSearchParams(window\.location.search);
    const token = params.get('token');
    if (token) {
      // set and remove token from url
      localStorage.setItem('auth\_token', token);
      window\.history.replaceState({}, document.title, window\.location.pathname);
      // update store
      import('../stores/authStore').then(({ setToken }) => setToken(token));
    }
  } catch (err) {
    // ignore
  }
}

// run on import if browser
if (typeof window !== 'undefined') captureTokenFromUrlIfPresent();
